<?php
declare(strict_types=1);
require __DIR__.'/TestDb.php';require dirname(__DIR__).'/app/Station.php';
use Petrol\{Db,Station,Problem};use function Petrol\uid;
$tmp=sys_get_temp_dir().'/petrolpos-workspace-'.uid();mkdir($tmp,0700,true);$count=0;
function ok(bool $v,string $message): void {global $count;if(!$v)throw new RuntimeException('FAIL: '.$message);$count++;echo "PASS $message\n";}
function no(callable $f,string $message): void {try{$f();}catch(Throwable $e){if(!$e instanceof Problem&&!$e instanceof PDOException)throw $e;ok(true,$message);return;}throw new RuntimeException('FAIL accepted: '.$message);}
function amount(int $c): string {return number_format($c/100,2,'.','');}
try{
    $db=test_database();$s=new Station($db);$u=$s->setup(['owner_name'=>'Owner','username'=>'owner','password'=>'Workspace-test-2026','station_name'=>'Workspace test','demo'=>true]);
    $snap=$s->snapshot($u);$viewer=array_merge($u,['role'=>'viewer']);$cashier=array_merge($u,['role'=>'cashier']);
    ok((int)$db->value('SELECT COUNT(*) FROM employees')===1,'New owner has a linked employee record');
    $employee=$s->saveEmployee(['code'=>'E002','name'=>'Attendant','designation'=>'DSM','phone'=>'123'],$u);
    $login=$s->master('user',['name'=>'Attendant','username'=>'attendant','password'=>'Attendant-test-2026','role'=>'cashier','employee_id'=>$employee['id']],$u);
    ok($s->find('employees',$employee['id'])['user_id']===$login['id'],'Users Admin links a new login to an existing employee');
    no(fn()=>$s->linkEmployee(['employee_id'=>$employee['id'],'user_id'=>$u['id']],$u),'One login cannot belong to two employee records');
    no(fn()=>$s->saveEmployee(['code'=>'BAD','name'=>'No','designation'=>'No'],$viewer),'Viewer cannot add employees');
    $n=$snap['nozzles'][0];$s->employeeStatus(['id'=>$employee['id'],'active'=>false],$u);
    no(fn()=>$s->openShift(['user_id'=>$login['id'],'label'=>'Blocked','nozzle_ids'=>[$n['id']]],$u),'Inactive employee cannot start a shift');
    $s->employeeStatus(['id'=>$employee['id'],'active'=>true],$u);
    $bank=$s->createBank(['code'=>'MAIN','name'=>'Operating account','bank_name'=>'Bank','opening_balance'=>'100000'],$u);
    $other=$s->createBank(['code'=>'RESERVE','name'=>'Reserve','bank_name'=>'Bank','opening_balance'=>'0'],$u);
    ok($s->bankBalance($bank['id'])===10000000,'Bank opening balance is recorded as a bank ledger entry');
    no(fn()=>$s->createBank(['code'=>'BAD','name'=>'Bad','bank_name'=>'Bank','opening_balance'=>'-1'],$u),'Negative opening balance needs overdraft permission');
    $request=['request_key'=>uid(),'bank_account_id'=>$bank['id'],'to_account_id'=>$other['id'],'kind'=>'transfer','amount'=>'1000','reference'=>'TR-1','note'=>'Reserve transfer'];
    $first=$s->workOnce('bank_move',$request,$u,fn()=>$s->bankMove($request,$u));$retry=$s->workOnce('bank_move',$request,$u,fn()=>$s->bankMove($request,$u));
    ok($first['id']===$retry['id']&&$s->bankBalance($bank['id'])===9900000&&$s->bankBalance($other['id'])===100000,'Transfer retry posts one balanced pair of bank entries');
    $changed=array_merge($request,['amount'=>'2000']);no(fn()=>$s->workOnce('bank_move',$changed,$u,fn()=>$s->bankMove($changed,$u)),'Changed-payload retry is rejected');
    no(fn()=>$s->bankMove(array_merge($request,['to_account_id'=>'missing']),$u),'Invalid destination rolls back transfer');
    ok($s->bankBalance($bank['id'])===9900000,'Failed transfer leaves source account unchanged');
    no(fn()=>$s->bankMove(array_merge($request,['amount'=>'9999999']),$u),'Bank overdraft is blocked');
    no(fn()=>$s->bankMove($request,$cashier),'Cashier cannot administer bank transfers');
    $p=$snap['products'][0];$v=$snap['suppliers'][0];$tank=$s->find('tanks',$n['tank_id']);$stock=$s->balance($tank['id']);
    $purchase=$s->productPurchase(['supplier_id'=>$v['id'],'product_id'=>$p['id'],'invoice_no'=>'P001','quantity'=>'10','cost'=>'100','paid_amount'=>'200','bank_account_id'=>$bank['id']],$u);
    ok($s->find('products',$p['id'])['stock_milli']===30000&&(int)$db->value('SELECT balance_cents FROM supplier_balances WHERE id=?',[$v['id']])===80000,'Product purchase adds stock and creates unpaid vendor balance');
    ok($s->bankBalance($bank['id'])===9880000,'Paid-at-purchase amount reduces selected bank');
    no(fn()=>$s->delivery(['tank_id'=>$tank['id'],'supplier_id'=>$v['id'],'invoice_no'=>'P001','liters'=>'1','cost_per_liter'=>'100'],$u),'Vendor invoice reference is unique across fuel and product purchases');
    ok($s->balance($tank['id'])===$stock,'Duplicate purchase does not change fuel stock');
    no(fn()=>$s->productPurchase(['supplier_id'=>$v['id'],'product_id'=>$p['id'],'invoice_no'=>'P002','quantity'=>'1','cost'=>'100','paid_amount'=>'10'],$u),'Paid purchase requires a bank account');
    ok($s->find('products',$p['id'])['stock_milli']===30000,'Incomplete payment rolls back the whole purchase');
    $s->supplierPayment(['supplier_id'=>$v['id'],'bank_account_id'=>$bank['id'],'amount'=>'300','reference'=>'VP001'],$u);
    ok((int)$db->value('SELECT balance_cents FROM supplier_balances WHERE id=?',[$v['id']])===50000&&$s->bankBalance($bank['id'])===9850000,'Vendor payment reduces both payable and bank exactly once');
    no(fn()=>$s->supplierPayment(['supplier_id'=>$v['id'],'bank_account_id'=>$bank['id'],'amount'=>'501','reference'=>'BAD'],$u),'Vendor overpayment is rejected');
    $shift=$s->openShift(['label'=>'Morning','user_id'=>$login['id'],'opening_cash'=>'1000','nozzle_ids'=>[$n['id']]],$u);
    no(fn()=>$s->employeeStatus(['id'=>$employee['id'],'active'=>false],$u),'Employee with open shift cannot be deactivated');
    no(fn()=>$s->linkEmployee(['employee_id'=>$employee['id'],'user_id'=>''],$u),'Open shift prevents reassignment of employee login');
    no(fn()=>$s->userAccess(['id'=>$login['id'],'role'=>'viewer'],$u),'Open shift prevents changing operator to viewer');
    $s->bankMove(['bank_account_id'=>$bank['id'],'kind'=>'shift_deposit','shift_id'=>$shift['id'],'amount'=>'100','reference'=>'DEP1','note'=>'Cash deposit'],$u);
    ok($s->shiftTotals($shift['id'])['expected_cash']===90000&&$s->bankBalance($bank['id'])===9860000,'Shift cash deposit moves drawer cash into bank without sales');
    $s->expense(['payment_method'=>'bank','bank_account_id'=>$bank['id'],'category'=>'Utilities','amount'=>'50','note'=>'Power bill'],$u);
    ok($s->bankBalance($bank['id'])===9855000&&$s->shiftTotals($shift['id'])['expected_cash']===90000,'Bank expense reduces bank only');
    $rate=$s->price($tank['fuel_type_id']);$customer=$snap['customers'][0];
    $sale=$s->sale(['idempotency_key'=>uid(),'shift_id'=>$shift['id'],'customer_id'=>$customer['id'],'items'=>[['kind'=>'fuel','nozzle_id'=>$n['id'],'quantity'=>'1']],'payments'=>[['method'=>'credit','amount'=>amount($rate)]]],$u);
    $salesCount=$db->value('SELECT COUNT(*) FROM sales');
    $s->customerReceipt(['customer_id'=>$customer['id'],'amount'=>amount($rate),'method'=>'bank','bank_account_id'=>$bank['id'],'reference'=>'CR1'],$u);
    ok((int)$db->value('SELECT balance_cents FROM customer_balances WHERE id=?',[$customer['id']])===0&&$s->bankBalance($bank['id'])===9855000+$rate,'Bank customer collection clears receivable and credits bank');
    ok($db->value('SELECT COUNT(*) FROM sales')===$salesCount&&$s->shiftTotals($shift['id'])['expected_cash']===90000,'Bank credit collection changes neither revenue nor drawer cash');
    $closed=$s->closeShift(['shift_id'=>$shift['id'],'readings'=>[$n['id']=>number_format(($n['last_meter_ml']+1000)/1000,3,'.','')],'counted_cash'=>'800','counted_card'=>'0','counted_qr'=>'0','note'=>'Approved cash shortage'],$u);
    ok($s->pumpReceivables()[0]['outstanding_cents']===10000,'Completed shift shortage becomes pump receivable');
    $recovery=['request_key'=>uid(),'settlement_id'=>$closed['id'],'method'=>'bank','bank_account_id'=>$bank['id'],'amount'=>'60','reference'=>'RECOVERY1'];
    $s->workOnce('pump_receipt',$recovery,$u,fn()=>$s->pumpReceipt($recovery,$u));$s->workOnce('pump_receipt',$recovery,$u,fn()=>$s->pumpReceipt($recovery,$u));
    ok($s->pumpReceivables()[0]['outstanding_cents']===4000&&(int)$db->value('SELECT COUNT(*) FROM pump_receipts')===1,'Pump receipt retry reduces the shortage once');
    no(fn()=>$s->pumpReceipt(array_merge($recovery,['amount'=>'41']),$u),'Pump shortage cannot be over-collected');
    $next=$s->openShift(['label'=>'Next shift','opening_cash'=>'0','nozzle_ids'=>[$n['id']]],$u);
    $s->pumpReceipt(['settlement_id'=>$closed['id'],'method'=>'cash','shift_id'=>$next['id'],'amount'=>'40','reference'=>'RECOVERY2'],$u);
    ok($s->shiftTotals($next['id'])['expected_cash']===4000&&$s->pumpReceivables()[0]['outstanding_cents']===0,'Cash recovery clears shortage and increases new shift drawer');
    ok($db->value('SELECT COUNT(*) FROM sales')===$salesCount,'Shortage recovery never adds sales revenue');
    $dates=['from'=>'2000-01-01','to'=>'2099-12-31'];
    $vs=$s->ledgerStatement(array_merge(['kind'=>'vendor','id'=>$v['id']],$dates),$u);
    ok($vs['closing_cents']===50000&&count($vs['rows'])===3,'Vendor statement includes invoice, initial payment and later payment');
    $bs=$s->ledgerStatement(array_merge(['kind'=>'bank','id'=>$bank['id']],$dates),$u);
    ok($bs['closing_cents']===$s->bankBalance($bank['id']),'Bank statement closes at the account book balance');
    $db->run("UPDATE product_purchases SET received_at='2020-01-01T00:00:00Z' WHERE id=?",[$purchase['id']]);
    $period=$s->ledgerStatement(['kind'=>'vendor','id'=>$v['id'],'from'=>'2021-01-01','to'=>'2099-12-31'],$u);
    ok($period['opening_cents']===80000&&$period['closing_cents']===50000,'Date-filtered statement carries opening balance from historical entries');
    $ps=$s->ledgerStatement(array_merge(['kind'=>'pump','id'=>$n['pump_id']],$dates),$u);
    ok($ps['rows'][0]['net_ml']===1000&&$ps['rows'][0]['meter_value_cents']===$rate,'Pump statement uses meter less tests at the original price');
    no(fn()=>$s->ledgerStatement(array_merge(['kind'=>'bank','id'=>$bank['id']],$dates),$viewer),'Viewer cannot read bank ledger');
    no(fn()=>$s->ledgerStatement(['kind'=>'vendor','id'=>$v['id'],'from'=>'2026-02-30','to'=>'2026-03-01'],$u),'Invalid statement date is rejected');
    $entry=$db->one('SELECT * FROM bank_transactions WHERE bank_account_id=? LIMIT 1',[$bank['id']]);$balance=$s->bankBalance($bank['id']);
    $s->bankMatch(['id'=>$entry['id'],'statement_ref'=>'STMT 1 / line 1'],$u);
    ok($s->find('bank_transactions',$entry['id'])['matched_at']!==null&&$s->bankBalance($bank['id'])===$balance,'Manual matching records evidence without modifying amount');
    no(fn()=>$s->bankMatch(['id'=>$entry['id'],'statement_ref'=>'duplicate'],$u),'An already matched bank entry cannot be matched twice');
    $s->userAccess(['id'=>$login['id'],'role'=>'manager','password'=>'Replacement-pass-2026'],$u);
    ok(password_verify('Replacement-pass-2026',$s->find('users',$login['id'])['password_hash']),'Admin password reset updates the hashed password');
    no(fn()=>$s->userAccess(['id'=>$u['id'],'role'=>'viewer'],$u),'Owner cannot remove their own admin access');
    ok((int)$db->value('SELECT MAX(version) FROM schema_migrations')===10,'MySQL schema version stays valid after workspace transactions');
    echo "\n$count workspace checks passed. Isolated test files: $tmp\n";
}catch(Throwable $e){fwrite(STDERR,(string)$e."\n");exit(1);}
